from pathlib import Path

ROOT = Path('.')


def read(path):
    return (ROOT / path).read_text(encoding='utf-8')


def write(path, text):
    (ROOT / path).write_text(text, encoding='utf-8')


def replace_once(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected exactly one match, got {count}')
    return text.replace(old, new, 1)

# ---------------------------------------------------------------------------
# TrackMixController: origin-aware prepared pool, native fallback preload,
# same-ID final reconciliation, and removal of the unsafe seed-only/I2 replay.
# ---------------------------------------------------------------------------
path = 'app/src/main/java/io/github/alagga/gonesmart/TrackMixController.kt'
t = read(path)

t = replace_once(
    t,
    '''import java.util.concurrent.CountDownLatch\n''',
    '',
    'remove CountDownLatch import'
)

t = replace_once(
    t,
    '''internal data class TrackMixPreparedInitialPool(\n    val sessionId: Long,\n    val trackIds: List<Long>\n) {\n    companion object {\n        val EMPTY = TrackMixPreparedInitialPool(-1L, emptyList())\n    }\n}\n''',
    '''internal enum class TrackMixPreparedOrigin {\n    NONE,\n    SMART,\n    NATIVE_FALLBACK\n}\n\ninternal data class TrackMixPreparedInitialPool(\n    val sessionId: Long,\n    val trackIds: List<Long>,\n    val origin: TrackMixPreparedOrigin = TrackMixPreparedOrigin.SMART\n) {\n    companion object {\n        val EMPTY = TrackMixPreparedInitialPool(\n            sessionId = -1L,\n            trackIds = emptyList(),\n            origin = TrackMixPreparedOrigin.NONE\n        )\n    }\n}\n''',
    'prepared origin model'
)

t = replace_once(
    t,
    '''        @Volatile var provisionalCurrentQueuePosition: Int? = null\n        @Volatile var nextSourceBoundary: ObservedNativePositionCommand? = null\n        @Volatile var nextSourceBoundaryAmbiguous = false\n''',
    '''        @Volatile var provisionalCurrentQueuePosition: Int? = null\n        @Volatile var provisionalCurrentQueueEntryId: Long? = null\n        @Volatile var nextSourceBoundary: ObservedNativePositionCommand? = null\n        @Volatile var nextSourceBoundaryAmbiguous = false\n        @Volatile var nativeFallbackPrimedTrackId: Long? = null\n        @Volatile var nativeFallbackPrimedNextQueueEntryId: Long? = null\n        @Volatile var nativeFallbackPrimingFailed = false\n''',
    'pending native fallback state'
)

start = t.index('    /**\n     * Record bounded natural MusicService Int->void calls while a zero-provider')
end = t.index('    /**\n     * Called from the proven native qr.z refill hook', start)
new_observer = '''    /**\n     * Record the bounded natural MusicService current+1 boundary for the\n     * request-local native-fallback path. The hook runs BEFORE GMMP reads the\n     * next AudioSource, so the temporary current+1 row can be retargeted to\n     * the exact native fallback Track ID that will also occupy final slot 2.\n     * No native playback method is replayed later.\n     */\n    fun observeNativePositionCommand(\n        service: Any?,\n        method: java.lang.reflect.Method,\n        value: Int?\n    ) {\n        val request = pending ?: return\n        if (request.stage != "WAIT_PLAY") return\n        if (request.prePlayPrepared.origin != TrackMixPreparedOrigin.NATIVE_FALLBACK) return\n        if (request.prePlayTarget == null || service == null || value == null) return\n        if (method.parameterCount != 1 ||\n            (method.parameterTypes[0] != Integer.TYPE &&\n                method.parameterTypes[0] != Integer::class.java) ||\n            method.returnType != Void.TYPE\n        ) return\n        val isMusicService = generateSequence<Class<*>>(service.javaClass) {\n            it.superclass\n        }.any { it.name == "gonemad.gmmp.playback.service.MusicService" }\n        if (!isMusicService) return\n\n        val key = method.declaringClass.name + "." + method.name +\n            "(int)@" + System.identityHashCode(service)\n        val observed = ObservedNativePositionCommand(\n            key = key,\n            service = WeakReference(service),\n            method = method.apply { isAccessible = true },\n            value = value,\n            looper = Looper.myLooper(),\n            observedAt = SystemClock.elapsedRealtime()\n        )\n        val existing = request.nativePositionCommands.indexOfFirst { it.key == key }\n        if (existing >= 0) {\n            request.nativePositionCommands[existing] = observed\n        } else {\n            if (request.nativePositionCommands.size >= 12) return\n            request.nativePositionCommands += observed\n        }\n\n        tryPromoteNextSourceBoundary(request)\n        val boundary = request.nextSourceBoundary ?: return\n        if (boundary.key != key || boundary.value != value) return\n        primeNativeFallbackCurrentPlusOne(request)\n    }\n\n    private fun primeNativeFallbackCurrentPlusOne(request: Pending): Boolean {\n        request.nativeFallbackPrimedTrackId?.let { return true }\n        if (request.nativeFallbackPrimingFailed) return false\n        val target = request.prePlayTarget ?: return false\n        val prepared = request.prePlayPrepared\n        if (prepared.origin != TrackMixPreparedOrigin.NATIVE_FALLBACK) return false\n        val fallbackTrackId = prepared.trackIds.firstOrNull() ?: return false\n        val currentEntryId = request.provisionalCurrentQueueEntryId ?: return false\n        val currentPosition = request.provisionalCurrentQueuePosition ?: return false\n        val autoDj = nativeAutoDj?.get() ?: return false\n\n        val nextEntryId = runCatching {\n            GmmpQueueMutationBridge(\n                autoDj = autoDj,\n                verifiedPositionWriter = nativePositionWriterProvider(autoDj),\n                currentQueueEntryIdHint = currentEntryId\n            ).retargetTrackMixPreloadedNext(\n                selectedTrackId = target.id,\n                replacementTrackId = fallbackTrackId,\n                expectedCurrentQueuePosition = currentPosition\n            )\n        }.onFailure {\n            Log.e(\n                TAG,\n                "MIX NATIVE FALLBACK PRELOAD | primed=false | fail-closed=true",\n                it\n            )\n        }.getOrNull()\n\n        if (nextEntryId == null) {\n            request.nativeFallbackPrimingFailed = true\n            return false\n        }\n        request.nativeFallbackPrimedTrackId = fallbackTrackId\n        request.nativeFallbackPrimedNextQueueEntryId = nextEntryId\n        Log.i(\n            TAG,\n            "MIX NATIVE FALLBACK PRELOAD | primed=true" +\n                " | currentEntry=" + currentEntryId +\n                " | nextEntry=" + nextEntryId +\n                " | track=" + fallbackTrackId +\n                " | position=" + (currentPosition + 1) +\n                " | boundary=natural-current-plus-one"\n        )\n        return true\n    }\n\n'''
t = t[:start] + new_observer + t[end:]

t = replace_once(
    t,
    '''        val prepared = request.prePlayPrepared\n        if (prepared.trackIds.isEmpty()) return null\n''',
    '''        val prepared = request.prePlayPrepared\n        if (prepared.origin != TrackMixPreparedOrigin.SMART) return null\n        if (prepared.trackIds.isEmpty()) return null\n''',
    'bootstrap only smart origin'
)

t = replace_once(
    t,
    '''                Log.i(\n                    TAG,\n                    "MIX PREPLAY SMART POOL | target=${resolution.track.id} | " +\n                        "requested=$requiredUpcoming | prepared=${request.prePlayPrepared.trackIds.size}"\n                )\n''',
    '''                Log.i(\n                    TAG,\n                    "MIX PREPLAY SMART POOL | target=${resolution.track.id} | " +\n                        "requested=$requiredUpcoming | prepared=${request.prePlayPrepared.trackIds.size} | " +\n                        "origin=${request.prePlayPrepared.origin}"\n                )\n                if (\n                    requiredUpcoming > 0 &&\n                    request.prePlayPrepared.origin == TrackMixPreparedOrigin.NONE\n                ) {\n                    Log.e(\n                        TAG,\n                        "MIX PREPLAY FALLBACK | no safe prepared/native fallback tracks; native Play not dispatched"\n                    )\n                    if (pending === request) pending = null\n                    main.post {\n                        fail(\n                            "Could not prepare a safe Track Auto-DJ queue for this song.",\n                            context\n                        )\n                    }\n                    return@execute\n                }\n''',
    'preplay safe abort'
)

old_zero_branch = '''                if (request.prePlayPrepared.trackIds.isEmpty()) {\n                    filled = fillZeroPoolNativeFallback(\n                        request = request,\n                        selectedId = selectedId,\n                        selectedEntryId = selectedEntryId,\n                        selectedQueuePosition = selectedQueuePosition,\n                        initial = initial,\n                        upcomingSetting = upcoming\n                    ) ?: run {\n                        fail(\n                            "Could not safely replace the source queue with native Auto-DJ tracks.",\n                            request.context\n                        )\n                        return\n                    }\n                } else {\n'''
new_zero_branch = '''                if (\n                    request.prePlayPrepared.origin ==\n                    TrackMixPreparedOrigin.NATIVE_FALLBACK\n                ) {\n                    filled = finalizeNativeFallbackPreparedQueue(\n                        request = request,\n                        selectedId = selectedId,\n                        selectedEntryId = selectedEntryId,\n                        selectedQueuePosition = selectedQueuePosition,\n                        initial = initial,\n                        upcomingSetting = upcoming\n                    ) ?: run {\n                        fail(\n                            "Could not safely finalize the native Track Auto-DJ fallback queue.",\n                            request.context\n                        )\n                        return\n                    }\n                } else if (request.prePlayPrepared.trackIds.isEmpty()) {\n                    Log.e(\n                        TAG,\n                        "MIX PREPLAY VERIFY | prepared origin empty after native Play; fail closed"\n                    )\n                    fail(\n                        "Could not safely prepare the Track Auto-DJ queue.",\n                        request.context\n                    )\n                    return\n                } else {\n'''
t = replace_once(t, old_zero_branch, new_zero_branch, 'replace zero-pool branch')

# Delete the unsafe manual replay + seed-only implementation, replace with
# final same-ID native fallback reconciliation.
start = t.index('    private fun invokeNextSourceBoundary(')
end = t.index('    private fun waitForSelectedSong(request: Pending): LoadedPlay?', start)
new_finalize = '''    private fun recoverNativeFallbackCurrentPlusOne(\n        request: Pending,\n        selectedId: Long,\n        selectedEntryId: Long\n    ): Boolean {\n        val fallbackTrackId = request.nativeFallbackPrimedTrackId ?: return false\n        val autoDj = nativeAutoDj?.get() ?: return false\n        val current = queueSnapshot(selectedEntryId) ?: return false\n        if (current.currentId != selectedId) return false\n        val currentPosition = current.currentQueuePosition ?: return false\n        val recovered = runCatching {\n            GmmpQueueMutationBridge(\n                autoDj = autoDj,\n                verifiedPositionWriter = nativePositionWriterProvider(autoDj),\n                currentQueueEntryIdHint = selectedEntryId\n            ).retargetTrackMixPreloadedNext(\n                selectedTrackId = selectedId,\n                replacementTrackId = fallbackTrackId,\n                expectedCurrentQueuePosition = currentPosition\n            ) != null\n        }.onFailure {\n            Log.e(TAG, "MIX NATIVE FALLBACK RECOVER | failed", it)\n        }.getOrDefault(false)\n        Log.i(\n            TAG,\n            "MIX NATIVE FALLBACK RECOVER | nextAligned=$recovered" +\n                " | track=" + fallbackTrackId +\n                " | currentPosition=" + currentPosition\n        )\n        return recovered\n    }\n\n    private fun finalizeNativeFallbackPreparedQueue(\n        request: Pending,\n        selectedId: Long,\n        selectedEntryId: Long,\n        selectedQueuePosition: Int,\n        initial: Int,\n        upcomingSetting: Int\n    ): Snapshot? {\n        val prepared = request.prePlayPrepared\n        val expectedFallbackCount = (initial - 1).coerceAtLeast(0)\n        if (prepared.origin != TrackMixPreparedOrigin.NATIVE_FALLBACK ||\n            prepared.trackIds.size != expectedFallbackCount\n        ) {\n            Log.e(\n                TAG,\n                "MIX NATIVE FALLBACK | prepared set incomplete" +\n                    " | expected=" + expectedFallbackCount +\n                    " | actual=" + prepared.trackIds.size\n            )\n            return null\n        }\n        if (expectedFallbackCount > 0 &&\n            (request.nativeFallbackPrimingFailed ||\n                request.nativeFallbackPrimedTrackId != prepared.trackIds.first())\n        ) {\n            Log.e(\n                TAG,\n                "MIX NATIVE FALLBACK | natural current+1 preload was not verified; source queue untouched"\n            )\n            return null\n        }\n\n        val autoDj = nativeAutoDj?.get() ?: return null\n        val rebaseWriter = nativeTrackMixPositionWriterProvider(\n            autoDj,\n            selectedQueuePosition\n        ) ?: run {\n            Log.e(\n                TAG,\n                "MIX NATIVE FALLBACK | passively verified Current writer unavailable; source queue untouched"\n            )\n            recoverNativeFallbackCurrentPlusOne(request, selectedId, selectedEntryId)\n            return null\n        }\n\n        request.stage = "RETARGETING"\n        val retargeted = runCatching {\n            GmmpQueueMutationBridge(\n                autoDj = autoDj,\n                verifiedPositionWriter = rebaseWriter,\n                currentQueueEntryIdHint = selectedEntryId\n            ).retargetTrackMixUpcoming(\n                selectedTrackId = selectedId,\n                smartTrackIds = prepared.trackIds,\n                targetQueueSize = initial\n            )\n        }.onFailure {\n            Log.e(TAG, "MIX NATIVE FALLBACK | same-ID queue reconciliation failed", it)\n        }.getOrDefault(false)\n        if (!retargeted) {\n            recoverNativeFallbackCurrentPlusOne(request, selectedId, selectedEntryId)\n            return null\n        }\n\n        val compact = runCatching {\n            GmmpQueueMutationBridge(\n                autoDj = autoDj,\n                verifiedPositionWriter = rebaseWriter,\n                currentQueueEntryIdHint = selectedEntryId\n            ).rebaseTrackMixZeroPoolInitialQueue(\n                selectedTrackId = selectedId,\n                expectedSize = initial\n            )\n        }.onFailure {\n            Log.e(TAG, "MIX NATIVE FALLBACK | final queue rebase failed", it)\n        }.getOrDefault(false)\n        if (!compact) {\n            recoverNativeFallbackCurrentPlusOne(request, selectedId, selectedEntryId)\n            return null\n        }\n\n        val expectedIds = TrackMixNativeFallbackPolicy.expectedQueueIds(\n            selectedTrackId = selectedId,\n            fallbackTrackIds = prepared.trackIds\n        )\n        val filled = queueSnapshot(selectedEntryId)?.takeIf { snapshot ->\n            snapshot.currentId == selectedId &&\n                snapshot.currentIndex == 0 &&\n                snapshot.currentQueuePosition == 1 &&\n                snapshot.ids == expectedIds\n        } ?: run {\n            recoverNativeFallbackCurrentPlusOne(request, selectedId, selectedEntryId)\n            return null\n        }\n\n        Log.i(\n            TAG,\n            "MIX NATIVE FALLBACK QUEUE | verified=true" +\n                " | preloadPreserved=" +\n                (request.nativeFallbackPrimedTrackId == prepared.trackIds.firstOrNull()) +\n                " | initial=" + initial +\n                " | current=" + selectedId +\n                " | followers=" + prepared.trackIds.joinToString(",")\n        )\n\n        armManagedAutoDjSession()\n        request.stage = "FILLING"\n        request.transitionalRefillSuppressed = false\n        sendCommand(request.context, COMMAND_AUTO_DJ)\n        nativeToastSuppressionUntilMs = SystemClock.elapsedRealtime() + 7_000L\n        awaitAutoDjCommandRefillBoundary(request)\n        Log.i(\n            TAG,\n            "MIX AUTO-DJ | command=sent-after-native-fallback-reconcile" +\n                " | initialSize=" + initial +\n                " | upcoming=" + upcomingSetting +\n                " | seed=" + selectedId +\n                " | manualPlaybackReplay=false"\n        )\n        return filled\n    }\n\n'''
t = t[:start] + new_finalize + t[end:]

# Store the temporary native CURRENT row identity together with its position so
# the natural current+1 hook can mutate only that exact queue row.
t = t.replace(
    '''                        request.provisionalCurrentQueuePosition =\n                            current.currentQueuePosition\n                        tryPromoteNextSourceBoundary(request)\n''',
    '''                        request.provisionalCurrentQueuePosition =\n                            current.currentQueuePosition\n                        request.provisionalCurrentQueueEntryId =\n                            identity.queueEntryId\n                        tryPromoteNextSourceBoundary(request)\n'''
)
t = t.replace(
    '''                request.provisionalCurrentQueuePosition = current.currentQueuePosition\n                tryPromoteNextSourceBoundary(request)\n''',
    '''                request.provisionalCurrentQueuePosition = current.currentQueuePosition\n                request.provisionalCurrentQueueEntryId = identity.queueEntryId\n                tryPromoteNextSourceBoundary(request)\n'''
)
if t.count('provisionalCurrentQueueEntryId =') < 2:
    raise SystemExit('did not patch both provisional current identity assignments')

if 'fillZeroPoolNativeFallback(' in t:
    raise SystemExit('unsafe fillZeroPoolNativeFallback runtime path still present')
if 'invokeNextSourceBoundary(' in t:
    raise SystemExit('unsafe invokeNextSourceBoundary runtime path still present')
write(path, t)

# ---------------------------------------------------------------------------
# Queue bridge: one-row same-ID current+1 prime before GMMP natural preload.
# ---------------------------------------------------------------------------
path = 'app/src/main/java/io/github/alagga/gonesmart/GmmpQueueMutationBridge.kt'
t = read(path)
anchor = '''    /**\n     * Retarget verified existing 4.2.1 upcoming rows without ever removing\n'''
method = '''    /**\n     * Retarget only the exact existing current+1 row while preserving its\n     * queue_id and queue_position. This is used before GMMP's natural\n     * next-AudioSource read so the decoder identity is established before any\n     * later source-list rebuild. No delete or playback-position write occurs.\n     */\n    fun retargetTrackMixPreloadedNext(\n        selectedTrackId: Long,\n        replacementTrackId: Long,\n        expectedCurrentQueuePosition: Int\n    ): Long? {\n        require(replacementTrackId > 0L)\n        require(expectedCurrentQueuePosition > 0)\n        val resolved = resolve(\n            requireDelete = false,\n            requireStatePosition = false\n        )\n        val current = resolved.context.items.singleOrNull {\n            it.state == QueueItemState.CURRENT\n        } ?: error("Track Mix preload Current queue entry unavailable")\n        currentQueueEntryIdHint?.let { expected ->\n            require(current.queueEntryId == expected) {\n                "Track Mix preload Current queue_id changed"\n            }\n        }\n        require(\n            current.track.id == selectedTrackId &&\n                current.queuePosition == expectedCurrentQueuePosition\n        ) {\n            "Track Mix preload Current identity/position changed"\n        }\n        val next = resolved.context.items.singleOrNull {\n            it.queuePosition == expectedCurrentQueuePosition + 1\n        } ?: error("Track Mix preload current+1 row unavailable")\n        val row = resolved.rows.singleOrNull {\n            number(resolved.queueId, it).toLong() == next.queueEntryId\n        } ?: error("Track Mix preload current+1 native entity unavailable")\n\n        if (next.track.id != replacementTrackId) {\n            setLong(resolved.trackId, row, replacementTrackId)\n            resolved.update.invoke(resolved.dao, arrayListOf(row))\n        }\n\n        val verified = GmmpQueueReader().read(\n            autoDj,\n            verifiedPositionWriter?.read(),\n            currentQueueEntryIdHint\n        ) ?: error("Track Mix preload verification unavailable")\n        val verifiedCurrent = verified.items.singleOrNull {\n            it.state == QueueItemState.CURRENT\n        } ?: error("Track Mix preload Current disappeared")\n        val verifiedNext = verified.items.singleOrNull {\n            it.queuePosition == expectedCurrentQueuePosition + 1\n        } ?: error("Track Mix preload current+1 disappeared")\n        check(\n            verifiedCurrent.queueEntryId == current.queueEntryId &&\n                verifiedCurrent.track.id == selectedTrackId &&\n                verifiedCurrent.queuePosition == expectedCurrentQueuePosition &&\n                verifiedNext.queueEntryId == next.queueEntryId &&\n                verifiedNext.track.id == replacementTrackId\n        ) {\n            "Track Mix preload current+1 retarget failed verification"\n        }\n        Log.i(\n            TAG,\n            "TRACK MIX PRELOAD NEXT | verified=true" +\n                " | currentEntry=" + current.queueEntryId +\n                " | nextEntry=" + next.queueEntryId +\n                " | position=" + verifiedNext.queuePosition +\n                " | track=" + replacementTrackId\n        )\n        return next.queueEntryId\n    }\n\n'''
if anchor not in t:
    raise SystemExit('queue bridge insert anchor missing')
t = t.replace(anchor, method + anchor, 1)

# Remove the now-retired seed-only method so future repairs cannot silently
# reintroduce the proven null-current+1 gap.
seed_start = t.index('    /**\n     * r36 zero-provider path.')
seed_end = t.index('    /**\n     * Native qr.z owns the replacement Track IDs.', seed_start)
t = t[:seed_start] + t[seed_end:]
write(path, t)

# ---------------------------------------------------------------------------
# Pure fallback policy + tests.
# ---------------------------------------------------------------------------
policy_path = ROOT / 'app/src/main/java/io/github/alagga/gonesmart/TrackMixNativeFallbackPolicy.kt'
policy_path.write_text('''package io.github.alagga.gonesmart\n\ninternal object TrackMixNativeFallbackPolicy {\n    fun selectNativeTrackIds(\n        rawTrackIds: List<Long>,\n        selectedTrackId: Long,\n        requested: Int\n    ): List<Long> {\n        if (requested <= 0) return emptyList()\n        return rawTrackIds.asSequence()\n            .filter { it > 0L && it != selectedTrackId }\n            .distinct()\n            .take(requested)\n            .toList()\n    }\n\n    fun expectedQueueIds(\n        selectedTrackId: Long,\n        fallbackTrackIds: List<Long>\n    ): List<Long> = listOf(selectedTrackId) + fallbackTrackIds\n\n    fun preservesPreloadedNext(\n        primedTrackId: Long?,\n        fallbackTrackIds: List<Long>\n    ): Boolean =\n        fallbackTrackIds.isEmpty() || primedTrackId == fallbackTrackIds.first()\n}\n''', encoding='utf-8')

test_path = ROOT / 'app/src/test/java/io/github/alagga/gonesmart/TrackMixNativeFallbackPolicyTest.kt'
test_path.write_text('''package io.github.alagga.gonesmart\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertFalse\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\n\nclass TrackMixNativeFallbackPolicyTest {\n    @Test\n    fun `native selection excludes selected invalid and duplicate IDs`() {\n        assertEquals(\n            listOf(7L, 8L, 9L),\n            TrackMixNativeFallbackPolicy.selectNativeTrackIds(\n                rawTrackIds = listOf(0L, 42L, 7L, 7L, -2L, 8L, 9L),\n                selectedTrackId = 42L,\n                requested = 3\n            )\n        )\n    }\n\n    @Test\n    fun `native selection remains bounded`() {\n        assertEquals(\n            listOf(1L, 2L),\n            TrackMixNativeFallbackPolicy.selectNativeTrackIds(\n                rawTrackIds = listOf(1L, 2L, 3L),\n                selectedTrackId = 99L,\n                requested = 2\n            )\n        )\n    }\n\n    @Test\n    fun `final queue keeps selected then exact fallback order`() {\n        assertEquals(\n            listOf(42L, 7L, 8L, 9L),\n            TrackMixNativeFallbackPolicy.expectedQueueIds(42L, listOf(7L, 8L, 9L))\n        )\n    }\n\n    @Test\n    fun `preloaded current plus one must equal final first fallback`() {\n        assertTrue(\n            TrackMixNativeFallbackPolicy.preservesPreloadedNext(7L, listOf(7L, 8L))\n        )\n        assertFalse(\n            TrackMixNativeFallbackPolicy.preservesPreloadedNext(9L, listOf(7L, 8L))\n        )\n        assertTrue(\n            TrackMixNativeFallbackPolicy.preservesPreloadedNext(null, emptyList())\n        )\n    }\n}\n''', encoding='utf-8')

# ---------------------------------------------------------------------------
# GoneSmartModule: r44 marker and read-only native preselection when providers
# have no suitable Track Mix matches.
# ---------------------------------------------------------------------------
path = 'app/src/main/java/io/github/alagga/gonesmart/GoneSmartModule.kt'
t = read(path)
t = replace_once(t, '"gmmp421-r39"', '"gmmp421-r44"', 'compat revision')

old_tail = '''        Log.i(\n            TAG,\n            "SMART DJ TRACK MIX PREPLAY | complete | requested=$requestedTracks | " +\n                "prepared=${preparedIds.size} | " + recommendationPool.describe(sessionId)\n        )\n        return TrackMixPreparedInitialPool(sessionId, preparedIds)\n    }\n\n    private fun ensureRecommendationPoolReady(\n'''
new_tail = '''        Log.i(\n            TAG,\n            "SMART DJ TRACK MIX PREPLAY | complete | requested=$requestedTracks | " +\n                "prepared=${preparedIds.size} | " + recommendationPool.describe(sessionId)\n        )\n        if (preparedIds.isNotEmpty()) {\n            return TrackMixPreparedInitialPool(\n                sessionId = sessionId,\n                trackIds = preparedIds,\n                origin = TrackMixPreparedOrigin.SMART\n            )\n        }\n\n        val nativeFallbackAllowed =\n            networkStateReader.getState() == GoneSmartNetworkState.OFFLINE ||\n                options.fallbackToNativeAutoDjWhenNoSuitableTracks\n        if (nativeFallbackAllowed) {\n            val nativeIds = preselectTrackMixNativeFallback(\n                autoDjInstance = autoDjInstance,\n                selectedTrackId = selectedTrack.id,\n                requestedTracks = requestedTracks\n            )\n            if (nativeIds.size == requestedTracks) {\n                Log.i(\n                    TAG,\n                    "SMART DJ TRACK MIX NATIVE PRESELECT | requested=$requestedTracks" +\n                        " | selected=${nativeIds.size}" +\n                        " | boundary=verified-selection-dao"\n                )\n                return TrackMixPreparedInitialPool(\n                    sessionId = sessionId,\n                    trackIds = nativeIds,\n                    origin = TrackMixPreparedOrigin.NATIVE_FALLBACK\n                )\n            }\n            Log.w(\n                TAG,\n                "SMART DJ TRACK MIX NATIVE PRESELECT | requested=$requestedTracks" +\n                    " | selected=${nativeIds.size} | fail-closed=true"\n            )\n        }\n        return TrackMixPreparedInitialPool.EMPTY\n    }\n\n    private fun preselectTrackMixNativeFallback(\n        autoDjInstance: Any,\n        selectedTrackId: Long,\n        requestedTracks: Int\n    ): List<Long> {\n        if (requestedTracks <= 0) return emptyList()\n        return runCatching {\n            val trackDaoField = findField(\n                type = autoDjInstance.javaClass,\n                name = "r"\n            ).apply { isAccessible = true }\n            val trackDao = trackDaoField.get(autoDjInstance)\n                ?: error("GMMP Auto-DJ track DAO unavailable")\n            val selection = resolveAutoDjSelectionMethod(trackDao.javaClass).apply {\n                isAccessible = true\n            }\n            val sampleCount = maxOf(\n                requestedTracks + 4,\n                requestedTracks * 3\n            ).coerceAtMost(32)\n            val rows = (selection.invoke(trackDao, sampleCount) as? List<*>)\n                ?.filterNotNull()\n                ?: emptyList()\n            val rawIds = rows.mapNotNull { row ->\n                runCatching {\n                    val idField = findField(\n                        type = row.javaClass,\n                        name = "a"\n                    ).apply { isAccessible = true }\n                    (idField.get(row) as? Number)?.toLong()\n                }.getOrNull()\n            }\n            TrackMixNativeFallbackPolicy.selectNativeTrackIds(\n                rawTrackIds = rawIds,\n                selectedTrackId = selectedTrackId,\n                requested = requestedTracks\n            )\n        }.onFailure {\n            Log.e(\n                TAG,\n                "SMART DJ TRACK MIX NATIVE PRESELECT | verified selection boundary failed",\n                it\n            )\n        }.getOrDefault(emptyList())\n    }\n\n    private fun ensureRecommendationPoolReady(\n'''
t = replace_once(t, old_tail, new_tail, 'preplay native preselection')
write(path, t)

# ---------------------------------------------------------------------------
# Durable docs: the old seed-only + replay invariant is explicitly retired.
